mapper.select:
select t.person_name,t.person_name personName,t.person_way,t.person_way personWay,t.res_way,t.res_way
resWay,t.machine_id,t.machine_id machineId,t.org_layer,t.org_layer orgLayer,t.lmr_id,t.lmr_id
lmrId,t.person_id,t.person_id personId,t.status_cd,t.status_cd statusCd,t.target_layer,t.target_layer
targetLayer,t.room_id,t.room_id roomId,t.room_name,t.room_name roomName, t.create_time createTime,
td.name resWayName, td1.name personWayName, lm.machine_name machineName
from lift_machine_reservation t
left join t_dict td on t.res_way = td.status_cd and td.table_name = 'lift_machine_reservation' and td.table_columns = 'res_way'
left join t_dict td1 on t.person_way = td1.status_cd and td1.table_name = 'lift_machine_reservation' and td1.table_columns = 'person_way'
left join lift_machine lm on t.machine_id = lm.machine_id
where 1 =1 and lm.status_cd = '0'

    and t.person_name= #{personName}


    and t.person_way= #{personWay}


    and t.res_way= #{resWay}


    and t.machine_id= #{machineId}


    and t.org_layer= #{orgLayer}


    and t.lmr_id= #{lmrId}


    and t.person_id= #{personId}


    and t.status_cd= #{statusCd}


    and t.target_layer= #{targetLayer}


    and t.room_id= #{roomId}


    and t.room_name= #{roomName}

order by t.create_time desc

    limit #{page}, #{row}

